+import type { Shot } from "@/lib/guide";
+import { OVERLAY, overlay, type OverlayPrimitive, type Size } from "@/lib/guide-overlay";
+
+const { colours } = OVERLAY;
+const STROKE = { fill: "none", strokeLinecap: "round", strokeLinejoin: "round" } as const;
+
+function Primitive({ p }: { p: OverlayPrimitive }) {
+  switch (p.kind) {
+    case "vignette":
+      return <path d={p.d} fill="black" fillOpacity={OVERLAY.vignetteOpacity} fillRule="evenodd" />;
+    case "ring":
+      return (
+        <rect x={p.x} y={p.y} width={p.w} height={p.h} rx={OVERLAY.targetCorner}
+          fill="none" stroke={colours.tint} strokeWidth={OVERLAY.ringWidth} />
+      );
+    case "path":
+      return (
+        <path d={p.d} {...STROKE} stroke={colours.tint} pathLength={1}
+          className={p.role === "movement" ? "guide-mv" : "guide-ar"}
+          strokeWidth={p.role === "arrow" ? OVERLAY.arrowWidth : OVERLAY.movementWidth} />
+      );
+    case "finger":
+      return (
+        <circle cx={p.cx} cy={p.cy} r={OVERLAY.fingerDiameter / 2} fill="white"
+          fillOpacity={OVERLAY.fingerFillOpacity} stroke={colours.tint} strokeWidth={OVERLAY.fingerRingWidth} />
+      );
+    case "holdRing":
+      return p.outer ? (
+        <circle className="guide-hr guide-hr-outer" cx={p.cx} cy={p.cy}
+          r={(OVERLAY.fingerDiameter + OVERLAY.outerHoldRingGrowth) / 2} fill="none"
+          stroke={colours.tint} strokeOpacity={OVERLAY.outerHoldRingOpacity}
+          strokeWidth={OVERLAY.outerHoldRingWidth} strokeDasharray={OVERLAY.outerHoldRingDash} />
+      ) : (
+        <circle className="guide-hr" cx={p.cx} cy={p.cy} r={(OVERLAY.fingerDiameter + OVERLAY.holdRingGrowth) / 2}
+          fill="none" stroke={colours.tint} strokeWidth={OVERLAY.holdRingWidth} strokeDasharray={OVERLAY.holdRingDash} />
+      );
+    case "badge":
+      return (
+        <g>
+          <circle cx={p.cx} cy={p.cy} r={OVERLAY.badgeDiameter / 2} fill={colours.textPrimary}
+            stroke="white" strokeWidth={OVERLAY.badgeOutline} />
+          <text x={p.cx} y={p.cy} fill="white" fontSize={OVERLAY.badgeFontSize} fontWeight={700}
+            style={{ fontVariantNumeric: "tabular-nums" }} textAnchor="middle" dominantBaseline="central">
+            {p.number}
+          </text>
+        </g>
+      );
+  }
+}
+
+/** The overlay as one group per callout (ring through badge), so a story can light one step. */
+function callouts(shot: Shot, display: Size): { vignette: OverlayPrimitive; groups: OverlayPrimitive[][] } {
+  const [vignette, ...rest] = overlay(shot, display);
+  const groups: OverlayPrimitive[][] = [];
+  for (const p of rest) {
+    if (p.kind === "ring") groups.push([]);
+    groups[groups.length - 1].push(p);
+  }
+  if (groups.length !== shot.callouts.length) {
+    throw new Error(`guide overlay: ${shot.file} drew ${groups.length} callouts for ${shot.callouts.length}`);
+  }
+  return { vignette, groups };
+}
+
+/**
+ * One tour shot as the app shows it (vynr FeatureTourShotView): the real capture with the
+ * overlay drawn over it in the app's display space. `decorative` marks the pinned-phone copy,
+ * which repeats an inline shot and so is hidden from assistive technology.
+ */
+export default function ShotFrame({ shot, pixels, display, decorative = false, eager = false }: {
+  shot: Shot;
+  pixels: Size;
+  display: Size;
+  decorative?: boolean;
+  /** Load at once; every other shot is lazy, since /guide carries all of them. */
+  eager?: boolean;
+}) {
+  const { vignette, groups } = callouts(shot, display);
+  return (
+    <div className="guide-shot"
+      style={{ width: display.width, aspectRatio: `${display.width} / ${display.height}`,
+        ["--guide-aspect" as string]: display.width / display.height }}
+      aria-hidden={decorative || undefined}>
+      {/* eslint-disable-next-line @next/next/no-img-element -- a real capture at its own size; no optimiser rewrite */}
+      <img src={`/guide/${shot.file}`} alt={decorative ? "" : shot.alt} width={pixels.width} height={pixels.height}
+        loading={eager ? undefined : "lazy"} />
+      <svg viewBox={`0 0 ${display.width} ${display.height}`} aria-hidden="true" focusable="false">
+        <Primitive p={vignette} />
+        {groups.map((group, i) => (
+          <g key={shot.callouts[i].number} className="guide-c" data-n={shot.callouts[i].number}>
+            {group.map((p, j) => <Primitive key={j} p={p} />)}
+          </g>
+        ))}
+        <rect x={0.5} y={0.5} width={display.width - 1} height={display.height - 1} rx={OVERLAY.imageCorner}
+          fill="none" stroke={colours.cardStroke} strokeWidth={OVERLAY.cardStrokeWidth} />
+      </svg>
+    </div>
+  );
+}

import { createHash } from 'crypto'
import fs from 'fs'
import path from 'path'
import { displaySpace, jpegSize, type Size } from './guide-overlay'

// The Guide to vynr is written once, in vynr's guide/chapters (SJAM-1041). vynr's
// scripts/build_guide.py writes the generated bundle this module reads:
// content/guide/guide.json and public/guide/*.jpg. Neither is ever edited here
// (ADR-WEB-0001 ADDENDUM-002). The bundle is verified on load, so a hand edit, a stale frame
// or a stamp that disagrees with its release fails the build instead of reaching the site.
// Spec: vynr docs/superpowers/specs/2026-10-21-guide-single-source-design.md §6–§7.
const BUNDLE_PATH = path.join(process.cwd(), 'content/guide/guide.json')
const FRAMES_DIR = path.join(process.cwd(), 'public/guide')
const NAME = 'content/guide/guide.json'

/** The /guide index groups, in index order (spec §6). A group with no chapters is not shown. */
export const GROUPS = [
  { id: 'getting-around', heading: 'Getting around' },
  { id: 'your-wines', heading: 'Your wines' },
  { id: 'time-and-memory', heading: 'Time and memory' },
  { id: 'your-data', heading: 'Your data' },
] as const

const TAG = /^v(\d+\.\d+(?:\.\d+)?)-build\d+-source$/
const SHA = /^[0-9a-f]{40}$/
const DIGEST = /^[0-9a-f]{64}$/

export interface Trace {
  fingers: 1 | 2
  from: [number, number]
  to: [number, number]
  hold: boolean
  motion: 'parallel' | 'spread' | 'pinch' | 'hold'
}

export interface Callout {
  number: number
  text: string
  /** x, y, width, height, normalised to the shot. */
  target: [number, number, number, number]
  badge: [number, number]
  trace: Trace | null
}

export interface Shot {
  file: string
  alt: string
  callouts: Callout[]
}

/** A tour page exactly as the app's FeatureTourCatalog.pages holds it (spec §7 projection). */
export interface Tour {
  id: string
  title: string
  message: string
  shots: Shot[]
}

export interface Chapter {
  id: string
  title: string
  group: string
  summary: string | null
  tour: Tour | null
  /** Raw Markdown: the web-only depth. */
  body: string
}

export interface GuideBundle {
  guideSourceCommit: string
  appSourceCommit: string
  describes: string
  appVersion: string
  bootstrapEqualityDigest: string | null
  contentHash: string
  chapters: Chapter[]
  images: Record<string, string>
}

/** RFC 8785 canonical JSON: keys sorted by UTF-16 code unit, no whitespace, ES number form. */
export function jcsBytes(value: unknown): string {
  if (value === null || typeof value === 'boolean' || typeof value === 'string') return JSON.stringify(value)
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new Error(`canonical bytes: non-finite number ${value}`)
    return JSON.stringify(value)
  }
  if (Array.isArray(value)) return `[${value.map(jcsBytes).join(',')}]`
  if (typeof value === 'object') {
    const entries = Object.keys(value).sort().map(key => `${JSON.stringify(key)}:${jcsBytes((value as Record<string, unknown>)[key])}`)
    return `{${entries.join(',')}}`
  }
  throw new Error(`canonical bytes: unsupported value ${String(value)}`)
}

export function sha256Hex(data: string | Buffer): string {
  return createHash('sha256').update(data).digest('hex')
}

/** The digest that proves the bundle's tour equals the described build's tour (spec §7). */
export function tourProjectionDigest(bundle: GuideBundle): string {
  return sha256Hex(jcsBytes(bundle.chapters.flatMap(c => (c.tour ? [c.tour] : []))))
}

/** Every rule the bundle must meet; throws naming the field. */
export function verifyBundle(bundle: GuideBundle, framesDir: string): void {
  const fail = (field: string, problem: string): never => {
    throw new Error(`${NAME}: ${field}: ${problem}`)
  }
  if (!Array.isArray(bundle.chapters)) fail('chapters', 'must be a list')
  if (typeof bundle.images !== 'object' || bundle.images === null) fail('images', 'must be an object')
  if (!SHA.test(bundle.guideSourceCommit)) fail('guideSourceCommit', 'not a 40-hex commit')
  if (!SHA.test(bundle.appSourceCommit)) fail('appSourceCommit', 'not a 40-hex commit')
  const tag = bundle.describes.match(TAG)
  if (!tag) return fail('describes', `${bundle.describes} is not a v<version>-build<N>-source tag`)
  if (bundle.appVersion !== tag[1]) fail('appVersion', `${bundle.appVersion} disagrees with ${bundle.describes}`)

  const groups: readonly string[] = GROUPS.map(g => g.id)
  const ids = new Set<string>()
  for (const chapter of bundle.chapters) {
    if (ids.has(chapter.id)) fail('chapters', `duplicate id ${chapter.id}`)
    ids.add(chapter.id)
    if (!groups.includes(chapter.group)) fail(`${chapter.id}.group`, `unknown group ${chapter.group}`)
    if (chapter.tour === null && !chapter.summary) fail(`${chapter.id}.summary`, 'a chapter without a tour needs a summary')
    if (chapter.tour !== null && chapter.tour.id !== chapter.id) fail(`${chapter.id}.tour.id`, 'differs from the chapter id')
  }

  const used = new Set(bundle.chapters.flatMap(c => c.tour?.shots.map(s => s.file) ?? []))
  for (const name of used) if (!(name in bundle.images)) fail('images', `${name} is used by a tour but not listed`)
  for (const [name, hash] of Object.entries(bundle.images)) {
    if (!used.has(name)) fail('images', `${name} is listed but no tour uses it`)
    const file = path.join(framesDir, name)
    if (!fs.existsSync(file)) fail('images', `${name} is missing from public/guide`)
    if (sha256Hex(fs.readFileSync(file)) !== hash) fail('images', `${name} does not match its sha256`)
  }

  const content = sha256Hex(jcsBytes({ chapters: bundle.chapters, images: bundle.images }))
  if (content !== bundle.contentHash) fail('contentHash', `does not reproduce (computed ${content})`)

  const bootstrapped = bundle.guideSourceCommit !== bundle.appSourceCommit
  if (!bootstrapped && bundle.bootstrapEqualityDigest !== null) {
    fail('bootstrapEqualityDigest', 'must be null when the guide and app commits are the same')
  }
  if (bootstrapped) {
    if (bundle.bootstrapEqualityDigest === null || !DIGEST.test(bundle.bootstrapEqualityDigest)) {
      fail('bootstrapEqualityDigest', 'required when the guide and app commits differ')
    }
    if (bundle.bootstrapEqualityDigest !== tourProjectionDigest(bundle)) {
      fail('bootstrapEqualityDigest', 'is not the tour projection digest of this bundle')
    }
  }
}

let cached: GuideBundle | undefined

/** The verified bundle; a bad bundle throws, so `next build` fails rather than render it. */
export function getGuide(): GuideBundle {
  if (!cached) {
    const bundle = JSON.parse(fs.readFileSync(BUNDLE_PATH, 'utf8')) as GuideBundle
    verifyBundle(bundle, FRAMES_DIR)
    cached = bundle
  }
  return cached
}

export function getChapter(id: string): Chapter | undefined {
  return getGuide().chapters.find(c => c.id === id)
}

/** The previous and next chapters in source order. */
export function neighbours(id: string): { previous?: Chapter; next?: Chapter } {
  const chapters = getGuide().chapters
  const index = chapters.findIndex(c => c.id === id)
  return { previous: chapters[index - 1], next: index >= 0 ? chapters[index + 1] : undefined }
}

/** The chapter's one line on the index and in its meta description: the tour message or the summary. */
export function chapterLine(chapter: Chapter): string {
  return chapter.tour?.message ?? chapter.summary ?? ''
}

export function versionStamp(bundle: GuideBundle): string {
  return `Guide for vynr ${bundle.appVersion}`
}

/** A frame's pixel size, read from the JPEG, and its size in the app's display space. */
export function frameSize(file: string): { pixels: Size; display: Size } {
  const pixels = jpegSize(fs.readFileSync(path.join(FRAMES_DIR, file)))
  const { width, height } = displaySpace(pixels.width, pixels.height)
  return { pixels, display: { width, height } }
}
import type { Callout, Shot, Trace } from './guide'

// The in-app tour's overlay (vynr FeatureTourShotView, SJAM-568/570/603) as SVG geometry, so
// the web guide draws each shot the way the app does. Everything is in the app's display
// space: the capture fitted into a 300 × 400 pt box, the box the app lays a shot out in. Every
// constant below is the app's, and each function translates one Swift function line for line.
// Spec: vynr docs/superpowers/specs/2026-10-21-guide-single-source-design.md §6.
export const OVERLAY = {
  box: { width: 300, height: 400 },
  imageCorner: 18,
  cardStrokeWidth: 1,
  vignetteOpacity: 0.38,
  targetInset: 4,
  targetCorner: 8,
  ringWidth: 2.5,
  badgeDiameter: 24,
  badgeFontSize: 13,
  badgeOutline: 1.5,
  arrowWidth: 2,
  arrowHead: 7,
  fingerDiameter: 20,
  fingerFillOpacity: 0.92,
  fingerRingWidth: 2.5,
  movementWidth: 3,
  movementHead: 9,
  headSpread: 0.6,
  twoFingerSpacing: 13,
  holdRingGrowth: 12,
  holdRingWidth: 2,
  holdRingDash: '3 3',
  outerHoldRingGrowth: 24,
  outerHoldRingWidth: 1.5,
  outerHoldRingDash: '3 4',
  outerHoldRingOpacity: 0.55,
  /** CellarCanvas, the canvas the tour's shots are drawn with. Used inside the overlay only. */
  colours: { tint: '#8C7360', textPrimary: '#262420', cardStroke: '#D4CFC4' },
} as const

export interface Size {
  width: number
  height: number
}

interface Point {
  x: number
  y: number
}

interface Rect extends Point {
  w: number
  h: number
}

export type OverlayPrimitive =
  | { kind: 'vignette'; d: string }
  | { kind: 'ring'; x: number; y: number; w: number; h: number }
  | { kind: 'path'; role: 'arrow' | 'movement'; d: string }
  | { kind: 'finger'; cx: number; cy: number }
  | { kind: 'holdRing'; cx: number; cy: number; outer: boolean }
  | { kind: 'badge'; cx: number; cy: number; number: number }

const JPEG_SOF = new Set([0xc0, 0xc1, 0xc2])

/** The pixel size from a JPEG's start-of-frame marker: the frame itself, never its filename. */
export function jpegSize(bytes: Buffer): Size {
  if (bytes[0] !== 0xff || bytes[1] !== 0xd8) throw new Error('jpegSize: not a JPEG')
  let offset = 2
  while (offset + 9 < bytes.length) {
    if (bytes[offset] !== 0xff) throw new Error(`jpegSize: bad marker at ${offset}`)
    const marker = bytes[offset + 1]
    if (JPEG_SOF.has(marker)) {
      return { height: bytes.readUInt16BE(offset + 5), width: bytes.readUInt16BE(offset + 7) }
    }
    offset += 2 + bytes.readUInt16BE(offset + 2)
  }
  throw new Error('jpegSize: no start-of-frame marker')
}

/** The capture fitted into the app's 300 × 400 pt box (`.scaledToFit()` in the app). */
export function displaySpace(width: number, height: number): Size & { scale: number } {
  const scale = Math.min(OVERLAY.box.width / width, OVERLAY.box.height / height)
  return { scale, width: width * scale, height: height * scale }
}

const round = (value: number) => Math.round(value * 1000) / 1000
const fmt = (p: Point) => `${round(p.x)} ${round(p.y)}`

function rect([x, y, w, h]: Callout['target'], size: Size): Rect {
  return { x: x * size.width, y: y * size.height, w: w * size.width, h: h * size.height }
}

function inset(r: Rect, by: number): Rect {
  return { x: r.x - by, y: r.y - by, w: r.w + 2 * by, h: r.h + 2 * by }
}

function roundedRect(r: Rect, c: number): string {
  const right = r.x + r.w
  const bottom = r.y + r.h
  return [
    `M ${fmt({ x: r.x + c, y: r.y })}`,
    `H ${round(right - c)} A ${c} ${c} 0 0 1 ${fmt({ x: right, y: r.y + c })}`,
    `V ${round(bottom - c)} A ${c} ${c} 0 0 1 ${fmt({ x: right - c, y: bottom })}`,
    `H ${round(r.x + c)} A ${c} ${c} 0 0 1 ${fmt({ x: r.x, y: bottom - c })}`,
    `V ${round(r.y + c)} A ${c} ${c} 0 0 1 ${fmt({ x: r.x + c, y: r.y })} Z`,
  ].join(' ')
}

/** A stroke to `end` with an arrowhead, as `movement` and `arrow` draw it. */
function arrowPath(start: Point, end: Point, unit: Point, head: number): string {
  const k = OVERLAY.headSpread
  const left = { x: end.x - unit.x * head - unit.y * head * k, y: end.y - unit.y * head + unit.x * head * k }
  const right = { x: end.x - unit.x * head + unit.y * head * k, y: end.y - unit.y * head - unit.x * head * k }
  return `M ${fmt(start)} L ${fmt(end)} M ${fmt(left)} L ${fmt(end)} L ${fmt(right)}`
}

/** `movement(from:to:)`: from the finger dot's edge to the end; nothing when shorter than a finger. */
function movement(start: Point, end: Point): OverlayPrimitive[] {
  const dx = end.x - start.x
  const dy = end.y - start.y
  const length = Math.hypot(dx, dy)
  if (length <= OVERLAY.fingerDiameter) return []
  const unit = { x: dx / length, y: dy / length }
  const origin = { x: start.x + (unit.x * OVERLAY.fingerDiameter) / 2, y: start.y + (unit.y * OVERLAY.fingerDiameter) / 2 }
  return [{ kind: 'path', role: 'movement', d: arrowPath(origin, end, unit, OVERLAY.movementHead) }]
}

/** `arrow(from:to:)`: badge edge to the nearest point of the target; nothing when the badge sits on it. */
function arrow(badge: Point, target: Rect): OverlayPrimitive[] {
  const end = {
    x: Math.min(Math.max(badge.x, target.x), target.x + target.w),
    y: Math.min(Math.max(badge.y, target.y), target.y + target.h),
  }
  const dx = end.x - badge.x
  const dy = end.y - badge.y
  const length = Math.hypot(dx, dy)
  const radius = OVERLAY.badgeDiameter / 2 + 2
  if (length <= radius + 6) return []
  const unit = { x: dx / length, y: dy / length }
  const start = { x: badge.x + unit.x * radius, y: badge.y + unit.y * radius }
  return [{ kind: 'path', role: 'arrow', d: arrowPath(start, end, unit, OVERLAY.arrowHead) }]
}

const finger = (p: Point): OverlayPrimitive => ({ kind: 'finger', cx: round(p.x), cy: round(p.y) })
const holdRing = (p: Point, outer: boolean): OverlayPrimitive => ({ kind: 'holdRing', cx: round(p.x), cy: round(p.y), outer })

/** `fingerTrace`: one finger of a spread or pinch, its movement then its dot. */
function fingerTrace(start: Point, end: Point): OverlayPrimitive[] {
  return [...movement(start, end), finger(start)]
}

/** `traceView`: the finger dot(s), the movement and, for a hold, the rings. */
function trace(t: Trace, size: Size): OverlayPrimitive[] {
  const from = { x: t.from[0] * size.width, y: t.from[1] * size.height }
  const to = { x: t.to[0] * size.width, y: t.to[1] * size.height }
  if (t.motion === 'hold') {
    // A press-and-hold: no arrow, because the gesture is the finger staying still.
    return [holdRing(from, false), holdRing(from, true), finger(from)]
  }
  if (t.motion === 'parallel') {
    // Two fingers sit side by side across the direction of travel.
    const offsets = t.fingers === 2 ? [-OVERLAY.twoFingerSpacing, OVERLAY.twoFingerSpacing] : [0]
    const vertical = Math.abs(to.y - from.y) > Math.abs(to.x - from.x)
    const across = vertical ? { x: 1, y: 0 } : { x: 0, y: 1 }
    return offsets.flatMap(offset => {
      const start = { x: from.x + across.x * offset, y: from.y + across.y * offset }
      const end = { x: to.x + across.x * offset, y: to.y + across.y * offset }
      return [...movement(start, end), finger(start), ...(t.hold ? [holdRing(end, false)] : [])]
    })
  }
  // Spread/pinch: the second finger mirrors the first through the point where the fingers meet
  // (the start of a spread, the end of a pinch), and they stay a finger apart there.
  const centre = t.motion === 'spread' ? from : to
  const outer = t.motion === 'spread' ? to : from
  const dx = outer.x - centre.x
  const dy = outer.y - centre.y
  const length = Math.max(Math.hypot(dx, dy), 1)
  const gap = { x: (dx / length) * OVERLAY.fingerDiameter, y: (dy / length) * OVERLAY.fingerDiameter }
  const near = { x: centre.x + gap.x, y: centre.y + gap.y }
  const mirroredNear = { x: centre.x - gap.x, y: centre.y - gap.y }
  const mirroredOuter = { x: 2 * centre.x - outer.x, y: 2 * centre.y - outer.y }
  return t.motion === 'spread'
    ? [...fingerTrace(near, outer), ...fingerTrace(mirroredNear, mirroredOuter)]
    : [...fingerTrace(outer, near), ...fingerTrace(mirroredOuter, mirroredNear)]
}

/** `overlay(in:)`: the vignette, then per callout its ring, its trace or arrow, and its badge. */
export function overlay(shot: Shot, size: Size): OverlayPrimitive[] {
  const targets = shot.callouts.map(c => inset(rect(c.target, size), OVERLAY.targetInset))
  const vignette = [
    `M 0 0 H ${round(size.width)} V ${round(size.height)} H 0 Z`,
    ...targets.map(t => roundedRect(t, OVERLAY.targetCorner)),
  ].join(' ')
  return [
    { kind: 'vignette', d: vignette },
    ...shot.callouts.flatMap((callout, index): OverlayPrimitive[] => {
      const target = targets[index]
      const badge = { x: callout.badge[0] * size.width, y: callout.badge[1] * size.height }
      return [
        { kind: 'ring', x: round(target.x), y: round(target.y), w: round(target.w), h: round(target.h) },
        ...(callout.trace ? trace(callout.trace, size) : arrow(badge, target)),
        { kind: 'badge', cx: round(badge.x), cy: round(badge.y), number: callout.number },
      ]
    }),
  ]
}

