    const enhancer = read('app/guide/GuideStoryEnhancer.tsx');
    assert.match(enhancer, /return null;\s*}\s*$/);
    assert.doesNotMatch(enhancer, /innerHTML|textContent|createElement|appendChild/);
    assert.equal(renderToStaticMarkup(createElement(GuidePage)).includes('is-enhanced'), false,
      'the server markup is the linear page; enhancement is added only in the browser');
  });

  it('keeps the inline shots in the accessibility tree when the phone takes over', () => {
    const css = read('app/globals.css');
    const rule = css.slice(css.indexOf('.guide-chapter.is-enhanced .guide-inline-shot {'));
    assert.match(rule.slice(0, rule.indexOf('}')), /clip-path: inset\(50%\)/);
    assert.doesNotMatch(css, /\.is-enhanced \.guide-inline-shot \{ display: none/);
  });

  it('sizes the reading line in pixels from the window height', () => {
    const enhancer = read('app/guide/GuideStoryEnhancer.tsx');
    assert.match(enhancer, /window\.innerHeight \* READING_BAND/);
    assert.match(enhancer, /min-width: 900px\) and \(min-height: 640px\)/, 'the 540 px phone pins only where it fits');
    assert.doesNotMatch(enhancer, /rootMargin: "-?\d+%/);
  });

  it('prints as the linear page, whatever the enhancement did', () => {
    const css = read('app/globals.css');
    const print = css.slice(css.indexOf('@media print {', css.indexOf('Guide to vynr (SJAM-1041')));
    const block = print.slice(0, print.indexOf('\n}\n'));
    assert.match(block, /\.is-enhanced \.guide-phone-col \{ display: none; \}/);
    assert.match(block, /\.is-enhanced \.guide-inline-shot \{[^}]*clip-path: none/);
    assert.match(block, /\.is-enhanced \.guide-step \{ min-height: 0; opacity: 1; \}/);
  });

  it('loads only the first shot at once; every other shot is lazy', () => {
    const imgs = [...indexHtml.matchAll(/<img [^>]*>/g)].map(m => m[0]);
    const eager = imgs.filter(i => !i.includes('loading="lazy"'));
    assert.equal(eager.length, 2, 'the first shot, inline and its phone copy');
    assert.ok(eager.every(i => i.includes(`/guide/${guide.chapters[0].tour!.shots[0].file}`)));
  });

  it('honours Reduce Motion: no animation or transition survives it', () => {
    const css = read('app/globals.css');
    const reduced = css.slice(css.indexOf('@media (prefers-reduced-motion: reduce)', css.indexOf('Guide to vynr (SJAM-1041')));
    assert.match(reduced, /animation: none/);
    assert.match(reduced, /transition: none/);
  });

  it('ships no forms, tracking or fetches', () => {
    for (const file of ['app/guide/page.tsx', 'app/guide/[chapter]/page.tsx', 'app/guide/ChapterStory.tsx',
      'app/guide/ShotFrame.tsx', 'app/guide/MovementMap.tsx', 'app/guide/GuideStoryEnhancer.tsx',
      'lib/guide.ts', 'lib/guide-overlay.ts']) {
      const source = read(file);
      assert.doesNotMatch(source, /<(?:form|input|textarea|button|script)\b/i, file);
      assert.doesNotMatch(source, /analytics|tracking pixel|\bfetch\(/i, file);
    }
  });
});

